<template>
  <section class="master-page">
    <div class="management-head"><div><div class="eyebrow">PRODUCT DATA <span>/</span> WAREHOUSE GOODS</div><h1>仓库货品</h1><p>维护实际采购、存放和拣货的货品主档。此页面不会调整现有 SKU 库存。</p></div><el-button v-if="canManage" type="primary" @click="openCreate">＋ 新增货品</el-button></div>
    <div class="master-toolbar"><el-input v-model="q" clearable placeholder="搜索编码、名称、规格或条码" style="max-width:360px" @keyup.enter="search"/><el-select v-model="status" clearable placeholder="全部状态" @change="search"><el-option label="启用" value="ACTIVE"/><el-option label="停用" value="INACTIVE"/></el-select><el-button @click="search">查询</el-button></div>
    <div class="table-card"><el-table :data="items" v-loading="loading" empty-text="暂无仓库货品"><el-table-column label="主图" width="80"><template #default="s"><ProductReferenceImage :reference="goodsImages.get(s.row.id)" :label="s.row.goodsCode" /></template></el-table-column><el-table-column prop="goodsCode" label="货品编码" min-width="140"/><el-table-column prop="goodsName" label="货品名称" min-width="180"/><el-table-column prop="specification" label="规格" min-width="140"/><el-table-column prop="barcode" label="条码" min-width="130"/><el-table-column prop="unit" label="单位" width="85"/><el-table-column prop="supplierName" label="默认供应商" min-width="130"/><el-table-column prop="referencePurchasePrice" label="参考采购价（人民币）" width="170"><template #default="s">{{ Number(s.row.referencePurchasePrice||0).toFixed(4) }}</template></el-table-column><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.status==='ACTIVE'?'success':'info'">{{ s.row.status==='ACTIVE'?'启用':'停用' }}</el-tag></template></el-table-column><el-table-column label="库位" width="80"><template #default="s"><el-button v-if="canViewLocations" link type="primary" @click="router.push({path:'/warehouse-locations',query:{goodsId:s.row.id}})">查看</el-button></template></el-table-column><el-table-column v-if="canViewImages" label="图片" width="90"><template #default="s"><el-button link type="primary" @click="imageGoods=s.row">多图</el-button></template></el-table-column><el-table-column v-if="canManage" label="操作" width="130" fixed="right"><template #default="s"><el-button link type="primary" @click="openEdit(s.row)">编辑</el-button><el-button v-if="s.row.status==='ACTIVE'" link type="warning" @click="deactivate(s.row)">停用</el-button></template></el-table-column></el-table><div class="master-pagination"><span>共 {{ total }} 条</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[10,20,50,100]" layout="sizes, prev, pager, next" :total="total" @current-change="load" @size-change="search"/></div></div>
    <el-dialog v-model="imageVisible" :title="`货品图片 · ${imageGoods?.goodsCode || ''} · ${imageGoods?.goodsName || ''} · ${imageGoods?.specification || '无规格'}`" width="min(1000px, calc(100vw - 24px))" destroy-on-close><ImageManager v-if="imageGoods" object-type="WAREHOUSE_GOODS" :object-id="imageGoods.id" :can-manage="canManageImages" /></el-dialog>
    <el-dialog v-model="visible" :title="editingId?'编辑仓库货品':'新增仓库货品'" width="min(680px, calc(100vw - 32px))"><el-form :model="form" label-position="top"><el-row :gutter="16"><el-col :span="12"><el-form-item label="货品编码" required><el-input v-model="form.goodsCode" maxlength="100"/></el-form-item></el-col><el-col :span="12"><el-form-item label="货品名称" required><el-input v-model="form.goodsName" maxlength="255"/></el-form-item></el-col><el-col :span="12"><el-form-item label="规格"><el-input v-model="form.specification" maxlength="255"/></el-form-item></el-col><el-col :span="12"><el-form-item label="条码"><el-input v-model="form.barcode" maxlength="100"/></el-form-item></el-col><el-col :span="12"><el-form-item label="单位" required><el-input v-model="form.unit" maxlength="32" placeholder="个、套、米等"/></el-form-item></el-col><el-col :span="12"><el-form-item label="默认供应商"><el-select v-model="form.defaultSupplierId" clearable filterable style="width:100%"><el-option v-for="s in suppliers" :key="s.id" :label="`${s.supplierName} · ${s.supplierCode}`" :value="s.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="参考采购价（人民币）"><el-input-number v-model="form.referencePurchasePrice" :min="0" :precision="4" :step="0.01" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="状态"><el-select v-model="form.status" style="width:100%"><el-option label="启用" value="ACTIVE"/><el-option label="停用" value="INACTIVE"/></el-select></el-form-item></el-col><el-col :span="24"><el-form-item label="备注"><el-input v-model="form.note" type="textarea" maxlength="1000"/></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { useRoute,useRouter } from 'vue-router'
import { api,type AuthUser } from '../api'
import ImageManager from '../components/ImageManager.vue'
import ProductReferenceImage from '../components/ProductReferenceImage.vue'
import { useProductReferences } from '../utils/productReferences'
const goodsImages=useProductReferences('WAREHOUSE_GOODS')
const props=defineProps<{user?:AuthUser}>();const router=useRouter(),route=useRoute();const canManage=computed(()=>props.user?.permissions.includes('button.goods.manage')??false),canViewLocations=computed(()=>props.user?.permissions.includes('warehouse.locations.view')??false),canViewImages=computed(()=>props.user?.permissions.includes('menu.images')??false),canManageImages=computed(()=>props.user?.permissions.includes('button.images.manage')??false)
type Item={id:number;goodsCode:string;goodsName:string;specification?:string;barcode?:string;unit:string;defaultSupplierId?:number;supplierName?:string;referencePurchasePrice:number;status:string;note?:string}
const items=ref<Item[]>([]),suppliers=ref<{id:number;supplierCode:string;supplierName:string}[]>([]),q=ref(''),status=ref(''),page=ref(1),pageSize=ref(20),total=ref(0),loading=ref(false),visible=ref(false),saving=ref(false),editingId=ref<number>()
const imageGoods=ref<Item>(),imageVisible=computed({get:()=>!!imageGoods.value,set:value=>{if(!value)imageGoods.value=undefined}})
const blank=()=>({goodsCode:'',goodsName:'',specification:'',barcode:'',unit:'个',defaultSupplierId:undefined as number|undefined,referencePurchasePrice:0,status:'ACTIVE',note:''});const form=reactive(blank())
onMounted(()=>{if(route.query.q)q.value=String(route.query.q);load();loadSuppliers()})
async function load(){loading.value=true;try{const p=new URLSearchParams({page:String(page.value),pageSize:String(pageSize.value)});if(q.value.trim())p.set('q',q.value.trim());if(status.value)p.set('status',status.value);const r=await api<{items:Item[];total:number}>(`/api/warehouse-goods?${p}`);items.value=r.items;total.value=r.total;void goodsImages.load(r.items.map(item=>item.id))}catch(e){ElMessage.error(e instanceof Error?e.message:'读取货品失败')}finally{loading.value=false}}
async function loadSuppliers(){try{suppliers.value=(await api<{suppliers:typeof suppliers.value}>('/api/warehouse-goods/lookups')).suppliers}catch(e){ElMessage.error(e instanceof Error?e.message:'供应商列表读取失败')}}
function search(){page.value=1;load()}
function openCreate(){editingId.value=undefined;Object.assign(form,blank());visible.value=true}
function openEdit(row:Item){editingId.value=row.id;Object.assign(form,{...blank(),...row});visible.value=true}
async function save(){if(!form.goodsCode.trim()||!form.goodsName.trim()||!form.unit.trim()){ElMessage.warning('请填写货品编码、名称和单位');return}saving.value=true;try{const method=editingId.value?'PUT':'POST',url=editingId.value?`/api/warehouse-goods/${editingId.value}`:'/api/warehouse-goods';await api(url,{method,body:JSON.stringify(form)});ElMessage.success(editingId.value?'货品已更新':'货品已创建');visible.value=false;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'保存货品失败')}finally{saving.value=false}}
async function deactivate(row:Item){try{await ElMessageBox.confirm(`停用“${row.goodsCode} · ${row.goodsName}”？既有组成清单仍保留引用。`,'停用仓库货品',{type:'warning'});await api(`/api/warehouse-goods/${row.id}/deactivate`,{method:'POST'});ElMessage.success('货品已停用');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'停用货品失败')}}
</script>
